window.__ModuleLoader__.load({
  id: 'dsh-jianlai-aliang-theme',
  factory: () => {
const STYLE_TEXT = "/* A Liang's rainy road: the original DSH surfaces remain interactive. */\nbody[data-jianlai-aliang-theme] {\n  --dsw-focus-ring-color: #cfab74;\n  --dsw-elevation-stroke-color: rgba(207,171,116,.42);\n  color: #f2f0e9;\n  background: #172532;\n}\nbody[data-jianlai-aliang-theme]::before {\n  content: '';\n  position: fixed;\n  inset: 0;\n  background: linear-gradient(90deg, rgba(16,31,42,.30), rgba(16,31,42,.03) 67%), url(\"data:image/webp;base64,\") 65% center / cover no-repeat;\n  pointer-events: none;\n}\nbody[data-jianlai-aliang-theme] #root { position: relative; background: transparent; }\nbody[data-jianlai-aliang-theme] :is(main,[role=\"main\"]) :is(h1,h2) {\n  color: #f2eee4;\n  text-shadow: 0 3px 20px rgba(12,28,38,.75);\n  font-family: \"STKaiti\", \"KaiTi\", \"Songti SC\", serif;\n}\nbody[data-jianlai-aliang-theme] :is(main,[role=\"main\"]) :is(textarea,[contenteditable=\"true\"]) { caret-color: #cfab74; }\nbody[data-jianlai-aliang-theme] button[data-turn-process][data-jianlai-aliang-running] {\n  position: relative;\n  color: #e4c596;\n  background: linear-gradient(90deg, transparent, #d7b989, transparent) 100% 100% / 230% 1px no-repeat;\n  animation: aliang-progress 3s linear infinite;\n}\nbody[data-jianlai-aliang-theme] button[data-turn-process][data-jianlai-aliang-running] > span:first-child { opacity: 0; }\nbody[data-jianlai-aliang-theme] button[data-turn-process][data-jianlai-aliang-running]::before {\n  content: '╱'; position: absolute; top: 0; left: 0; color: #e6c798; font-size: 22px;\n  animation: aliang-blade 2.7s ease-in-out infinite;\n}\nbody[data-jianlai-aliang-theme] button[data-turn-process][data-jianlai-aliang-running]::after {\n  content: attr(data-jianlai-aliang-label); position: absolute; left: 26px; top: 0;\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n  max-width: calc(100% - 26px); pointer-events: none;\n}\n@keyframes aliang-progress { from { background-position: 100% 100%; } to { background-position: -100% 100%; } }\n@keyframes aliang-blade { 0%, 100% { opacity: .56; transform: translate(-2px,2px); } 50% { opacity: 1; transform: translate(2px,-2px); } }\n@media (prefers-reduced-motion: reduce) {\n  body[data-jianlai-aliang-theme] button[data-turn-process][data-jianlai-aliang-running],\n  body[data-jianlai-aliang-theme] button[data-turn-process][data-jianlai-aliang-running]::before { animation: none; }\n}\n\n/* DSH 0.2 live status: preserve its accessible text and native clock. */\nbody[data-jianlai-aliang-theme] [data-chat-running][data-jianlai-aliang-running] [class*=\"runningIcon\"] {\n  position: relative; width: 22px; height: 22px; flex: none;\n}\nbody[data-jianlai-aliang-theme] [data-chat-running][data-jianlai-aliang-running] [class*=\"runningIcon\"] > *,\nbody[data-jianlai-aliang-theme] [data-chat-running][data-jianlai-aliang-running] [class*=\"runningText\"] { display: none !important; }\nbody[data-jianlai-aliang-theme] [data-chat-running][data-jianlai-aliang-running] [class*=\"runningIcon\"]::before {\n  content: '╱'; position: absolute; top: 0; left: 0; color: #e6c798; font-size: 22px;\n  animation: aliang-blade 2.7s ease-in-out infinite;\n\n}\nbody[data-jianlai-aliang-theme] [data-chat-running][data-jianlai-aliang-running] [class*=\"runningContent\"]::after {\n  content: attr(data-jianlai-aliang-live-label);\n  min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  color: inherit; line-height: 24px;\n}\n@media (prefers-reduced-motion: reduce) {\n  body[data-jianlai-aliang-theme] [data-chat-running][data-jianlai-aliang-running] [class*=\"runningIcon\"]::before { animation: none !important; }\n}\n";

const THEME = Object.freeze({
  id: 'jianlai-aliang',
  colorScheme: 'dark',
  tokens: Object.freeze({
    '--dsw-alias-bg-base': '#172532',
    '--dsw-alias-bg-layer-1': '#223340',
    '--dsw-alias-bg-layer-2': '#2b3d48',
    '--dsw-alias-bg-layer-3': '#344653',
    '--dsw-alias-bg-overlay': '#1b2a36',
    '--dsw-alias-bg-module-platform': '#22333f',
    '--dsw-alias-bg-multi-select': '#394852',
    '--dsw-alias-label-primary': '#f2f0e9',
    '--dsw-alias-label-secondary': '#d3dce0',
    '--dsw-alias-label-tertiary': '#b7c5cb',
    '--dsw-alias-label-caption': '#b6c7ce',
    '--dsw-alias-label-primary-inverted': '#172532',
    '--dsw-alias-brand-primary': '#cfab74',
    '--dsw-alias-state-business-primary': '#cfab74',
    '--dsw-alias-button-primary-fill': '#aa8050',
    '--dsw-alias-button-primary-hover': '#c49b68',
    '--dsw-alias-button-info-fill': '#547884',
    '--dsw-alias-button-info-hover': '#7399a1',
    '--dsw-alias-button-elevated-fill': '#324553',
    '--dsw-alias-button-floating-fill': '#344a59',
    '--dsw-alias-button-floating-hover': '#466172',
    '--dsw-alias-interactive-bg-hover': 'rgba(207,171,116,.14)',
    '--dsw-alias-interactive-bg-active': 'rgba(207,171,116,.22)',
    '--dsw-alias-interactive-bg-hover-solid': '#384b55',
    '--dsw-alias-border-l1': 'rgba(204,217,222,.18)',
    '--dsw-alias-border-l2': 'rgba(204,217,222,.28)',
    '--dsw-alias-border-l3': 'rgba(207,171,116,.42)',
    '--dsw-alias-markdown-code-block': '#1b2c37',
    '--dsw-alias-markdown-code-block-banner': '#2a3d48',
    '--dsw-alias-markdown-inline-code': '#304550',
    '--dsw-alias-markdown-tag': '#38505b',
    '--dsw-alias-scrollbar-bg-l1': '#50636e',
    '--dsw-alias-scrollbar-hover-l1': '#6b818a',
    '--dsw-alias-scrollbar-bg-l2': '#566d78',
    '--dsw-alias-scrollbar-hover-l2': '#78909a',
    '--dsw-alias-tooltip-bg': '#152430',
    '--dsw-specific-bubble': '#2c3f4a',
    '--dsw-specific-bubble-highlight': '#394c56',
    '--dsw-specific-sidebar-fill': '#1b2a36',
    '--dsw-specific-sidebar-nav-item-active': '#4a493d',
    '--dsw-specific-sidebar-nav-item-hover': '#344451',
    '--dsw-specific-input-major': '#263b47',
    '--dsw-specific-menu': '#243642',
    '--dsw-specific-selector': '#304854',
    '--dsw-specific-tip': '#304854',
  }),
});

const inject = ['theme'];

function formatRunningStatus(announcement, visible) {
  const status = announcement.trim();
  const label = visible.trim();
  if (status === '深度求索中') {
    if (label === status) return '雨落江湖 · 问剑中';
    const match = /^深度求索中[，,]\s*用时\s*(.+)$/.exec(label);
    return match ? `雨落江湖 · 已行 ${match[1]}` : null;
  }
  if (status === 'Deep diving...') {
    if (label === status) return 'Rain road · thinking';
    const match = /^Deep diving for\s+(.+)$/i.exec(label);
    return match ? `Rain road · ${match[1]}` : null;
  }
  return null;
}

function decorateRunningStatuses(root) {
  for (const button of root.querySelectorAll('button[data-turn-process]')) {
    const announcement = button.previousElementSibling;
    const label = announcement?.getAttribute('role') === 'status'
      ? formatRunningStatus(announcement.textContent ?? '', button.textContent ?? '') : null;
    if (label === null) {
      button.removeAttribute('data-jianlai-aliang-running');
      button.removeAttribute('data-jianlai-aliang-label');
    } else {
      button.setAttribute('data-jianlai-aliang-running', '');
      button.setAttribute('data-jianlai-aliang-label', label);
    }
  }
  // DSH 0.2 places the live status outside the completed process button.
  for (const row of root.querySelectorAll('[data-chat-running]')) {
    if (!row.matches?.('[data-chat-running]')) continue;
    const content = row.querySelector?.('[class*="runningContent"]');
    const native = row.querySelector?.('[class*="runningText"]');
    const visible = (native?.textContent ?? '').trim().replace(/(?:\.{3}|…)$/, '');
    const announcement = visible.startsWith('深度求索中') ? '深度求索中'
      : visible.toLowerCase().startsWith('deep diving') ? 'Deep diving...' : '';
    const themed = content && announcement ? formatRunningStatus(announcement, visible === 'Deep diving' ? 'Deep diving...' : visible) : null;
    if (themed === null) {
      row.removeAttribute('data-jianlai-aliang-running');
      content?.removeAttribute('data-jianlai-aliang-live-label');
    } else {
      if (row.getAttribute?.('data-jianlai-aliang-running') !== '') row.setAttribute('data-jianlai-aliang-running', '');
      if (content.getAttribute?.('data-jianlai-aliang-live-label') !== themed) content.setAttribute('data-jianlai-aliang-live-label', themed);
    }
  }
}

function apply(ctx) {
  ctx.effect(() => {
    const previous = ctx.theme.getTheme().preference;
    const unregister = ctx.theme.register(THEME);
    ctx.theme.setTheme(THEME.id);
    return () => {
      if (ctx.theme.getTheme().preference === THEME.id) ctx.theme.setTheme(previous);
      unregister();
    };
  }, 'jianlai-aliang: palette');
  ctx.effect(() => {
    if (typeof document === 'undefined' || !document.body) return;
    const style = document.createElement('style');
    style.id = 'dsh-jianlai-aliang-theme';
    style.textContent = STYLE_TEXT;
    document.head.appendChild(style);
    document.body.setAttribute('data-jianlai-aliang-theme', '');
    const observer = typeof MutationObserver === 'function'
      ? new MutationObserver(() => decorateRunningStatuses(document.body)) : null;
    if (observer) {
      decorateRunningStatuses(document.body);
      observer.observe(document.body, { childList: true, characterData: true, subtree: true });
    }
    return () => {
      observer?.disconnect();

      for (const row of document.body.querySelectorAll('[data-chat-running][data-jianlai-aliang-running]')) {
        row.removeAttribute('data-jianlai-aliang-running');
        row.querySelector?.('[class*="runningContent"]')?.removeAttribute('data-jianlai-aliang-live-label');
      }
      for (const button of document.body.querySelectorAll('button[data-jianlai-aliang-running]')) {
        button.removeAttribute('data-jianlai-aliang-running');
        button.removeAttribute('data-jianlai-aliang-label');
      }
      document.body.removeAttribute('data-jianlai-aliang-theme');
      style.remove();
    };
  }, 'jianlai-aliang: scene');
}

    return { apply, inject, THEME };
  }
});
